import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.InputStream;
import java.util.Set;
import java.util.TreeSet;

public class CF933C_V3 {
    public static final double TOLERANCE = 1e-10;
    static final boolean IS_JUDGE = System.getProperty("ONLINE_JUDGE") != null;
    public static InputReader reader;

    public static void main(String[] args) throws FileNotFoundException {
        if (!IS_JUDGE) {
            System.setIn(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF933C.in"));
        }
        reader = new InputReader(System.in);
        execute();
    }

    public static void execute() {
        int n = reader.nextInt();
        Circle[] circles = new Circle[n];

        for (int i = 0; i < n; i++) {
            circles[i] = new Circle(reader.nextInt(), reader.nextInt(), reader.nextInt());
        }

        if (n == 3 && !Circle.intersect(circles[0], circles[1])) {
            int result = 4;
            if (Circle.intersect2(circles[0], circles[2])) {
                result++;
            }
            if (Circle.intersect2(circles[1], circles[2])) {
                result++;
            }
            System.out.println(result);
            return;
        }

        int total = 1;
        TreeSet<Point> intersections = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            intersections.clear();
            total++;
            for (int j = 0; j < i; j++) {
                Circle.getIntersections(circles[i], circles[j], intersections);
            }
            if (intersections.size() >= 2) {
                total += intersections.size() - 1;
            }
        }

        System.out.println(total);
    }

    public static double getEuclideanDistance(Point p1, Point p2) {
        return Math.sqrt(getSquaredDistance(p1, p2));
    }

    public static double getSquaredDistance(Point p1, Point p2) {
        double dx = p1.x - p2.x;
        double dy = p1.y - p2.y;
        return dx * dx + dy * dy;
    }

    public static class Circle {
        Point center;
        int radius;

        public Circle(int x, int y, int r) {
            this.center = new Point(x, y);
            this.radius = r;
        }

        public static boolean intersect(Circle a, Circle b) {
            double d = getEuclideanDistance(a.center, b.center);
            return d <= a.radius + b.radius + TOLERANCE && d + TOLERANCE >= Math.abs(a.radius - b.radius);
        }

        public static boolean intersect2(Circle a, Circle b) {
            double d = getEuclideanDistance(a.center, b.center);
            return d < a.radius + b.radius && d > Math.abs(a.radius - b.radius);
        }

        public static void getIntersections(Circle a, Circle b, Set<Point> set) {
            if (!intersect(a, b)) {
                return;
            }

            Line segment = new Line(a.center, b.center);
            double d = getEuclideanDistance(a.center, b.center);
            double distToMidpoint = (d * d - b.radius * b.radius + a.radius * a.radius) / (2 * d);
            Point midpoint = a.center.translate(segment, distToMidpoint);
            Point direction = segment.getDirection().perpendicular();
            double height = Math.sqrt(a.radius * a.radius - distToMidpoint * distToMidpoint);
            Point firstPoint = midpoint.translate(direction, height);
            Point secondPoint = midpoint.translate(direction, -height);

            set.add(firstPoint);
            if (!secondPoint.equals(firstPoint)) {
                set.add(secondPoint);
            }
        }
    }

    public static class Point implements Comparable<Point> {
        double x, y;

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }

        public Point subtract(Point other) {
            return new Point(x - other.x, y - other.y);
        }

        public Point translate(Line line, double distance) {
            return translate(line.getDirection(), distance);
        }

        public Point translate(Point vector, double distance) {
            Point normalized = vector.normalize();
            return add(normalized.multiply(distance));
        }

        public Point add(Point other) {
            return new Point(x + other.x, y + other.y);
        }

        public Point multiply(double factor) {
            return new Point(x * factor, y * factor);
        }

        public Point normalize() {
            double magnitude = Math.sqrt(x * x + y * y);
            return divide(magnitude);
        }

        public Point divide(double divisor) {
            return new Point(x / divisor, y / divisor);
        }

        public Point perpendicular() {
            return new Point(-y, x);
        }

        @Override
        public boolean equals(Object obj) {
            Point other = (Point) obj;
            return Math.abs(x - other.x) < TOLERANCE && Math.abs(y - other.y) < TOLERANCE;
        }

        @Override
        public int compareTo(Point o) {
            if (equals(o)) {
                return 0;
            }
            if (Math.abs(x - o.x) < TOLERANCE) {
                return Double.compare(y, o.y);
            }
            return Double.compare(x, o.x);
        }
    }

    public static class Line {
        Point start;
        Point end;

        public Line(Point start, Point end) {
            this.start = start;
            this.end = end;
        }

        public Point getDirection() {
            return end.subtract(start);
        }

        public double getLength() {
            return getEuclideanDistance(start, end);
        }
    }

    public static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            while (ptr >= len) {
                try {
                    len = stream.read(buffer);
                } catch (Exception e) {
                }
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() {
            int c = read();
            while (c <= 32) c = read();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = read();
            }
            int value = 0;
            while (c > 32) {
                value = value * 10 + (c - '0');
                c = read();
            }
            return negative ? -value : value;
        }

        public boolean hasNext() {
            int c = read();
            while (c <= 32) c = read();
            return c != -1;
        }
    }
}
